interface I18nState {
  lang: Lang;
  setLang: (l: Lang) => void;
  t: (key: string) => string;
}

/**
 * Язык, на котором сейчас рисуется интерфейс. Обновляется провайдером при
 * каждой отрисовке, до детей, — поэтому справочники ниже, прочитанные во
 * время рендера, всегда отдают подпись на текущем языке.
 */
let CURRENT_LANG: Lang = (() => {
  try {
    const v = localStorage.getItem(STORAGE_KEY);
    return v === 'ru' || v === 'tg' ? v : DEFAULT_LANG;
  } catch {
    return DEFAULT_LANG;
  }
})();

/** Текущий язык интерфейса — для форматтеров вне React-компонентов. */
export function currentLang(): Lang {
  return CURRENT_LANG;
}

/** Перевод по ключу вне React-компонентов (справочники, форматтеры). */
export function tr(key: string, fallback?: string): string {
  return DICT[CURRENT_LANG]?.[key] ?? DICT.ru[key] ?? fallback ?? key;
}

/**
 * Справочник подписей «значение → подпись» на текущем языке. Подпись берётся
 * из словаря по ключу `${prefix}.${значение}`; ru — русские подписи на случай,
 * если ключа нет. Снаружи это обычный Record: SOURCE_LABEL[s],
 * Object.entries(…) — менять места использования не нужно.
 */
export function localized<K extends string>(prefix: string, ru: Record<K, string>): Record<K, string> {
  return new Proxy(ru, {
    get(target, key) {
      if (typeof key !== 'string' || !(key in target)) return (target as any)[key];
      return DICT[CURRENT_LANG]?.[`${prefix}.${key}`] ?? (target as any)[key];
    },
  });
}

const I18nContext = createContext<I18nState>({
  lang: DEFAULT_LANG,
  setLang: () => {},
  t: (k) => k,
});

export function I18nProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>(() => {
    try {
      const v = localStorage.getItem(STORAGE_KEY) as Lang | null;
      return v === 'ru' || v === 'tg' ? v : DEFAULT_LANG;
    } catch {
      return DEFAULT_LANG;
    }
  });
  useEffect(() => {
    try { localStorage.setItem(STORAGE_KEY, lang); } catch {}
    document.documentElement.setAttribute('lang', lang === 'tg' ? 'tg' : 'ru');
  }, [lang]);

  CURRENT_LANG = lang;
  const t = (key: string): string => DICT[lang]?.[key] ?? key;
  return (
    <I18nContext.Provider value={{ lang, setLang: setLangState, t }}>
      {/* key={lang}: при смене языка дерево перерисовывается целиком —
          иначе компонент, читающий справочник без useT, остался бы на
          старом языке. Ссылка, вход и кеш данных живут снаружи и не теряются. */}
      <Fragment key={lang}>{children}</Fragment>
    </I18nContext.Provider>
  );
}

export function useT() {
  return useContext(I18nContext);
}
